import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
import ItemList from 'flarum/common/utils/ItemList';
import CollectableCanvas from './CollectableCanvas';
import Link from 'flarum/common/components/Link';
import huntUrl from '../utils/huntUrl';
/**
 * The Collectable assembling as its Parts are found: found Parts on their layers, silhouettes for the rest.
 */
export default class CollectionView extends Component {
  view() {
    return m("div", {
      className: "CollectionView"
    }, this.viewItems().toArray());
  }
  viewItems() {
    const items = new ItemList();
    const hunt = this.attrs.hunt;
    const parts = this.parts();
    const found = parts.filter(part => part.isFound()).length;
    items.add('header', m("h3", {
      className: "CollectionView-title"
    }, huntUrl(hunt.slug()) ? m(Link, {
      href: huntUrl(hunt.slug())
    }, hunt.title()) : hunt.title(), m("span", {
      className: "CollectionView-progress"
    }, app.translator.trans('fof-scavenger-hunt.forum.collection.progress', {
      found,
      total: parts.length
    }))), 100);
    items.add('canvas', m(CollectableCanvas, {
      hunt: hunt,
      parts: parts
    }), 80);
    items.add('parts', m("ul", {
      className: "CollectionView-parts"
    }, parts.map(part => this.partItem(part))), 60);
    return items;
  }
  parts() {
    return (this.attrs.hunt.parts() || []).filter(Boolean).sort((a, b) => a.sort() - b.sort());
  }
  partItem(part) {
    const found = !!part.isFound();
    let detail;
    if (found) {
      detail = app.translator.trans('fof-scavenger-hunt.forum.collection.found');
    } else if (part.isRandom()) {
      detail = app.translator.trans('fof-scavenger-hunt.forum.collection.random_part');
    } else if (part.hint()) {
      detail = part.hint();
    } else {
      detail = app.translator.trans('fof-scavenger-hunt.forum.collection.no_hint');
    }
    return m("li", {
      className: classList('CollectionView-part', {
        'CollectionView-part--found': found
      })
    }, m(Icon, {
      name: found ? 'fas fa-check-circle' : 'far fa-circle',
      className: "CollectionView-partIcon"
    }), m("span", {
      className: "CollectionView-partName"
    }, part.name()), m("span", {
      className: "CollectionView-partDetail"
    }, detail));
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/components/CollectionView', CollectionView);