import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { activeHunts } from '../utils/activeHunts';
import CollectionView from './CollectionView';
export default class CollectionModal extends Modal {
  hunts = null;
  oninit(vnode) {
    super.oninit(vnode);
    Promise.all(activeHunts().map(hunt => app.store.find('scavenger-hunts', String(hunt.id), {
      include: 'parts'
    }))).then(hunts => {
      this.hunts = hunts;
      m.redraw();
    });
  }
  className() {
    return 'CollectionModal Modal--medium';
  }
  title() {
    return app.translator.trans('fof-scavenger-hunt.forum.collection.title');
  }
  content() {
    if (!this.hunts) {
      return m("div", {
        className: "Modal-body"
      }, m(LoadingIndicator, null));
    }
    return m("div", {
      className: "Modal-body"
    }, this.hunts.length ? this.hunts.map(hunt => m(CollectionView, {
      hunt: hunt
    })) : m("p", {
      className: "CollectionModal-empty"
    }, app.translator.trans('fof-scavenger-hunt.forum.collection.empty')));
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/components/CollectionModal', CollectionModal);