import Component from 'flarum/common/Component';
/**
 * The Collectable on its canvas: found Parts on their layers, silhouettes for the rest.
 */
export default class CollectableCanvas extends Component {
  view() {
    const {
      hunt,
      parts
    } = this.attrs;
    return m("div", {
      className: "CollectionView-canvas"
    }, hunt.imageUrl() && m("img", {
      className: "CollectionView-base",
      src: hunt.imageUrl(),
      alt: "",
      decoding: "async"
    }), parts.filter(part => part.layer()).map(part => this.layer(part)));
  }
  layer(part) {
    const layer = part.layer();
    const imageUrl = part.imageUrl();
    const position = {
      left: `${layer.x}%`,
      top: `${layer.y}%`,
      width: `${layer.width}%`,
      zIndex: String(layer.z)
    };
    if (!imageUrl) {
      return null;
    }
    if (this.attrs.complete || part.isFound()) {
      return m("img", {
        className: "CollectionView-layer",
        src: imageUrl,
        alt: part.name(),
        style: position,
        decoding: "async"
      });
    }

    // The hidden image sizes the box; the mask paints its shape in the theme's silhouette colour.
    return m("span", {
      className: "CollectionView-layer CollectionView-layer--silhouette",
      "aria-hidden": "true",
      style: {
        ...position,
        maskImage: `url("${imageUrl}")`,
        WebkitMaskImage: `url("${imageUrl}")`
      }
    }, m("img", {
      src: imageUrl,
      alt: "",
      decoding: "async"
    }));
  }
}
flarum.reg.add('fof-scavenger-hunt', 'forum/components/CollectableCanvas', CollectableCanvas);